css:
.print-format {
	page-width: 86mm;
	page-height: 54mm;
	margin: 0;
}

@page {
	margin: 8mm;
}

.bandhu-card {
	width: 86mm;
	height: 54mm;
	box-sizing: border-box;
	padding: 4mm;
	border: 0.4mm solid #1f3b73;
	border-radius: 3mm;
	font-family: Helvetica, Arial, sans-serif;
	color: #16233a;
	display: flex;
	flex-direction: column;
	justify-content: space-between;
}
.card-header {
	display: flex;
	justify-content: space-between;
	align-items: baseline;
	border-bottom: 0.3mm solid #1f3b73;
	padding-bottom: 1.5mm;
}
.card-brand { font-size: 10pt; font-weight: bold; color: #1f3b73; }
.card-issuer { font-size: 7pt; letter-spacing: 0.4mm; color: #5a6a85; }
.card-body { display: flex; justify-content: space-between; gap: 3mm; }
.card-details { flex: 1; min-width: 0; }
.field-label { font-size: 6pt; text-transform: uppercase; letter-spacing: 0.3mm; color: #5a6a85; }
.patient-name {
	font-size: 11pt;
	font-weight: bold;
	margin-bottom: 1.5mm;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.clinic-id { font-size: 13pt; font-weight: bold; letter-spacing: 0.5mm; font-family: "Courier New", monospace; }
.card-meta { margin-top: 1.5mm; font-size: 7pt; color: #5a6a85; line-height: 1.5; }
.card-meta span { white-space: nowrap; display: inline-block; }
.card-meta span + span { margin-left: 2mm; }
.card-abha {
	margin-top: 1mm;
	font-size: 7pt;
	color: #5a6a85;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}
.card-qr { width: 22mm; }
.card-qr img { width: 22mm; height: 22mm; }
.qr-missing { font-size: 6.5pt; color: #a33; }
.card-footer { font-size: 6.5pt; color: #5a6a85; text-align: center; }

html:
{%- set clinic_id = doc.custom_bandhu_id or "" -%}
{%- if clinic_id|length == 10 -%}
	{%- set grouped_clinic_id = clinic_id[:2] ~ " " ~ clinic_id[2] ~ " " ~ clinic_id[3:5] ~ " " ~ clinic_id[5:] -%}
{%- else -%}
	{%- set grouped_clinic_id = clinic_id -%}
{%- endif -%}
<div class="bandhu-card">
	<div class="card-header">
		<div class="card-brand">Bandhu Mobile Clinics</div>
		<div class="card-issuer">CMID</div>
	</div>

	<div class="card-body">
		<div class="card-details">
			<div class="field-label">Name</div>
			<div class="patient-name">{{ (doc.patient_name or "") | e }}</div>

			<div class="field-label">Clinic ID</div>
			<div class="clinic-id">{{ grouped_clinic_id | e }}</div>

			<div class="card-meta">
				{%- if doc.sex %}<span>{{ _("Sex") }}: {{ _(doc.sex) }}</span>{% endif -%}
				{%- if doc.dob %}<span>{{ _("DOB") }}: {{ frappe.utils.formatdate(doc.dob) }}</span>{% endif -%}
				{%- if doc.mobile %}<span>{{ _("Ph") }}: {{ doc.mobile | e }}</span>{% endif -%}
			</div>
			{%- if doc.custom_abha_id %}
			<div class="card-abha">{{ _("ABHA") }}: {{ doc.custom_abha_id | e }}</div>
			{%- endif %}
		</div>

		<div class="card-qr">
			{% if doc.custom_qr_code %}
				<img src="{{ get_qr_code_image_source(doc.custom_qr_code) | e }}" alt="{{ doc.custom_bandhu_id | e }}">
			{% else %}
				<div class="qr-missing">{{ _("No QR code") }}</div>
			{% endif %}
		</div>
	</div>

	<div class="card-footer">{{ _("Show this card at every visit.") }}</div>
</div>
